package africa.growtogether.platform.eip.payment;
import africa.growtogether.platform.common.persistence.AuditedTenantEntity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="eip_payment_reconciliations",indexes={@Index(name="ix_eip_recon_status",columnList="tenant_id,reconciliation_status,created_at")})
public class PaymentReconciliation extends AuditedTenantEntity {
 @Column(name="payment_transaction_id") private UUID paymentTransactionId; @Column(name="settlement_id") private UUID settlementId; @Column(name="provider_reference",length=180) private String providerReference; @Column(name="internal_amount",precision=19,scale=4) private BigDecimal internalAmount; @Column(name="provider_amount",precision=19,scale=4) private BigDecimal providerAmount; @Enumerated(EnumType.STRING) @Column(name="reconciliation_status",nullable=false,length=30) private ReconciliationStatus status; @Column(name="reconciled_at") private Instant reconciledAt; @Column(name="notes",columnDefinition="text") private String notes;
 protected PaymentReconciliation(){} public PaymentReconciliation(UUID tenantId,UUID tx,UUID settlement,String ref,BigDecimal internal,BigDecimal provider){setTenantId(tenantId);paymentTransactionId=tx;settlementId=settlement;providerReference=ref;internalAmount=internal;providerAmount=provider;status=(internal!=null&&provider!=null&&internal.compareTo(provider)==0)?ReconciliationStatus.MATCHED:ReconciliationStatus.AMOUNT_MISMATCH;reconciledAt=Instant.now();} public ReconciliationStatus status(){return status;} public UUID id(){return getId();}
}
